// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public {
    }

    function testFuzz_property(address owner, address collateralToken, address debtToken, address factoryAddr) public {
        vm.assume(owner != address(0));
        vm.assume(collateralToken != address(0));
        vm.assume(debtToken != address(0));
        vm.assume(factoryAddr != address(0));
        vm.assume(owner != collateralToken);
        bytes memory data = abi.encodePacked(owner, collateralToken, debtToken, factoryAddr);
        Cooler implementation = new Cooler();
        Cloner cloner = new Cloner();
        address payable instance = cloner.clone(address(implementation), data);
        c = Cooler(instance);
        address returnedCollateral = address(c.collateral());
        assertTrue(returnedCollateral == collateralToken);
    }
}

